15: function createCanvas (width, height, type) {
16:   return new Canvas(width, height, type)
17: }
18: 
19: function createImageData (array, width, height) {
20:   return new bindings.ImageData(array, width, height)
21: }
22: 
23: function loadImage (src) {
24:   return new Promise((resolve, reject) => {
25:     const image = new Image()
26: 
27:     function cleanup () {
28:       image.onload = null
29:       image.onerror = null
30:     }
31: 
32:     image.onload = () => { cleanup(); resolve(image) }
33:     image.onerror = (err) => { cleanup(); reject(err) }
34: 
35:     image.src = src
36:   })
37: }
