30: #define PREFERRED_ENCODING_ID TT_MAC_ID_ROMAN
31: #else
32: #define PREFERRED_PLATFORM_ID TT_PLATFORM_MICROSOFT
33: #define PREFERRED_ENCODING_ID TT_MS_ID_UNICODE_CS
34: #endif
