42: /*
43:  * Return a UTF-8 encoded string given a TrueType name buf+len
44:  * and its platform and encoding
45:  */
46: 
47: char *
48: to_utf8(FT_Byte* buf, FT_UInt len, FT_UShort pid, FT_UShort eid) {
49:   size_t ret_len = len * 4; // max chars in a utf8 string
50:   char *ret = (char*)malloc(ret_len + 1); // utf8 string + null
51: 
52:   if (!ret) return NULL;
53: 
54:   // In my testing of hundreds of fonts from the Google Font repo, the two types
55:   // of fonts are TT_PLATFORM_MICROSOFT with TT_MS_ID_UNICODE_CS encoding, or
56:   // TT_PLATFORM_MACINTOSH with TT_MAC_ID_ROMAN encoding. Usually both, never neither
57: 
58:   char const *fromcode;
59: 
60:   if (pid == TT_PLATFORM_MACINTOSH && eid == TT_MAC_ID_ROMAN) {
61:     fromcode = "MAC";
62:   } else if (pid == TT_PLATFORM_MICROSOFT && eid == TT_MS_ID_UNICODE_CS) {
63:     fromcode = "UTF-16BE";
64:   } else {
65:     free(ret);
66:     return NULL;
67:   }
68: 
69:   GIConv cd = g_iconv_open("UTF-8", fromcode);
70: 
71:   if (cd == (GIConv)-1) {
72:     free(ret);
73:     return NULL;
74:   }
75: 
76:   size_t inbytesleft = len;
77:   size_t outbytesleft = ret_len;
78: 
79:   size_t n_converted = g_iconv(cd, (char**)&buf, &inbytesleft, &ret, &outbytesleft);
80: 
81:   ret -= ret_len - outbytesleft; // rewind the pointers to their
82:   buf -= len - inbytesleft;      // original starting positions
83: 
84:   if (n_converted == (size_t)-1) {
85:     free(ret);
86:     return NULL;
87:   } else {
88:     ret[ret_len - outbytesleft] = '\0';
89:     return ret;
90:   }
91: }
