98: char *
99: get_family_name(FT_Face face) {
100:   FT_SfntName name;
101: 
102:   int best_rank = -1;
103:   char* best_buf = NULL;
104: 
105:   for (unsigned i = 0; i < FT_Get_Sfnt_Name_Count(face); ++i) {
106:     FT_Get_Sfnt_Name(face, i, &name);
