108:     if (name.name_id == TT_NAME_ID_FONT_FAMILY || name.name_id == TT_NAME_ID_PREFERRED_FAMILY) {
109:       char *buf = to_utf8(name.string, name.string_len, name.platform_id, name.encoding_id);
