111:       if (buf) {
112:         int rank = GET_NAME_RANK(name);
113:         if (rank > best_rank) {
114:           best_rank = rank;
115:           if (best_buf) free(best_buf);
116:           best_buf = buf;
117:         } else {
118:           free(buf);
119:         }
120:       }
121:     }
122:   }
123: 
124:   return best_buf;
125: }
