        break;
    case CAIRO_FORMAT_RGB16_565:
        bpc = 8; // 565 gets upconverted to 888
        png_color_type = PNG_COLOR_TYPE_RGB;
        break;
    case CAIRO_FORMAT_INVALID:
    default:
        status = CAIRO_STATUS_INVALID_FORMAT;
